import type { SourcedQuote } from './quoteTypes';

/**
 * Original, concise adaptations of identified passages, not verbatim quotations.
 * English and Turkish were written together; neither is a published translation.
 * The reference remains visible so a reflection cannot be mistaken for scripture.
 * Primary texts checked 2026-09-22: Quran.com, Sunnah.com, MIT Classics Archive,
 * and the public-domain James Legge editions at Project Gutenberg.
 */
type Draft = Omit<SourcedQuote, 'id'>;
const q = (reference: string, sura: string, text: string, tr: string, tags: string[] = []): Draft => ({
  text, tr, reference, source: `Quran ${reference}`,
  sourceTr: `Kur’an, ${sura} ${reference}`,
  sourceUrl: `https://quran.com/${reference.replace(':', '/')}`,
  category: 'faith', kind: 'adaptation', tags,
});
const h = (collection: string, collectionTr: string, reference: string, text: string, tr: string, tags: string[] = []): Draft => ({
  text, tr, reference, source: `Prophet Muhammad · ${collection} ${reference}`,
  sourceTr: `Hz. Muhammed · ${collectionTr} ${reference}`,
  sourceUrl: `https://sunnah.com/${collection === 'Nawawi 40' ? 'nawawi40' : collection === 'Bukhari' ? 'bukhari' : 'muslim'}:${reference}`,
  category: 'faith', kind: 'adaptation', tags,
});
const p = (author: string, authorTr: string, work: string, workTr: string, reference: string, sourceUrl: string, text: string, tr: string, tags: string[] = []): Draft => ({
  text, tr, reference, source: `${author} · ${work} ${reference}`,
  sourceTr: `${authorTr} · ${workTr} ${reference}`,
  sourceUrl, category: 'philosophy', kind: 'adaptation', tags,
});
const marcus = (reference: string, book: string, text: string, tr: string, tags: string[] = []) => p(
  'Marcus Aurelius', 'Marcus Aurelius', 'Meditations', 'Kendime Düşünceler', reference,
  `https://classics.mit.edu/Antoninus/meditations.${book}.html`, text, tr, tags,
);
const epictetus = (reference: string, text: string, tr: string, tags: string[] = []) => p(
  'Epictetus', 'Epiktetos', 'Enchiridion', 'El Kitabı', reference,
  'https://classics.mit.edu/Epictetus/epicench.html', text, tr, tags,
);
const aristotle = (reference: string, book: string, text: string, tr: string, tags: string[] = []) => p(
  'Aristotle', 'Aristoteles', 'Nicomachean Ethics', 'Nikomakhos’a Etik', reference,
  `https://classics.mit.edu/Aristotle/nicomachaen.${book}.html`, text, tr, tags,
);
const confucius = (reference: string, text: string, tr: string, tags: string[] = []) => p(
  'Confucius', 'Konfüçyüs', 'Analects (Legge)', 'Konuşmalar (Legge)', reference,
  'https://www.gutenberg.org/cache/epub/3330/pg3330-images.html', text, tr, tags,
);
const lao = (reference: string, text: string, tr: string, tags: string[] = []) => p(
  'Laozi', 'Laozi', 'Tao Te Ching', 'Tao Te Ching', reference,
  'https://www.gutenberg.org/files/216/216-h/216-h.htm', text, tr, tags,
);

const drafts: Draft[] = [
  // 60 distinct Quran passages. Reflection/adaptation labels are intentional.
  q('2:177', 'Bakara', 'Let faith reach the person in need. Integrity joins belief with generosity, promises kept, and patience when life becomes difficult.', 'İnancın ihtiyaç sahibine kadar ulaşsın. İyilik; inanmayı, paylaşmayı, verdiğin sözü tutmayı ve zor günlerde sabrı aynı hayatta buluşturur.', ['faith', 'courage']),
  q('2:261', 'Bakara', 'Picture a seed opening into many ears of grain. Giving for God is a hopeful act whose worth exceeds the handful you release.', 'Bir tanenin nice başağa dönüştüğünü düşün. Allah rızası için paylaşırken, elinden çıkan miktardan daha geniş bir hayra niyet et.', ['generosity', 'hope']),
  q('2:262', 'Bakara', 'After helping someone, protect the gift from reminders and humiliation. Let the person keep their dignity along with what you gave.', 'Birine yardım ettikten sonra iyiliğini başına kakma. Verdiğin şey onun ihtiyacını karşılasın; ardından gelen sözlerin onurunu incitmesin.', ['compassion']),
  q('2:267', 'Bakara', 'Give something you would gladly receive yourself. Generosity deserves care in the quality of the gift, not merely its existence.', 'Kendin gönül rahatlığıyla kabul etmeyeceğin şeyi başkasına sunma. Paylaşırken seçtiğin şeyin niteliğine de özen göster; muhatabın buna değer.', ['generosity']),
  q('2:271', 'Bakara', 'A quiet gift can protect someone from exposure. When helping, consider the comfort of the person receiving, not the audience watching.', 'Sessizce yapılan yardım, ihtiyaç sahibinin mahremiyetini koruyabilir. İyiliğin görülmesini düşünürken, yardım ettiğin kişinin nasıl hissedeceğini de gözet.', ['compassion']),
  q('2:280', 'Bakara', 'When a debtor is struggling, give them breathing room. Sometimes the most merciful use of your power is allowing another person more time.', 'Borçlu zor durumdaysa ona nefes alacak zaman tanı. Bazen elindeki imkânı en güzel kullanışın, bir insanı sıkıştırmaktan vazgeçmendir.', ['mercy']),
  q('2:256', 'Bakara', 'Faith cannot be forced into a heart. Keep room for conscience, and let conviction grow through understanding rather than pressure.', 'İnancı bir kalbe zorla yerleştiremezsin. Vicdana alan aç; kanaatin baskıyla değil, anlayışla ve insanın kendi yönelişiyle kök salmasına saygı duy.', ['faith']),
  q('2:269', 'Bakara', 'Wisdom is a generous gift. Make room to reflect on what you learn, so knowledge can become sound judgment.', 'Hikmet büyük bir hayırdır. Öğrendiklerini yalnızca biriktirme; üzerinde düşünmeye de vakit ayır ki bilgin, isabetli bir anlayışa dönüşebilsin.', ['wisdom']),
  q('2:148', 'Bakara', 'People turn in different directions. Put your energy into competing in goodness; let your next step bring a real benefit.', 'İnsanlar farklı yönlere dönerken sen hayırda yarışmaya yönel. Enerjini yalnız kıyaslamaya harcama; sıradaki adımın bir iyiliğe dokunsun.', ['action']),
  q('2:201', 'Bakara', 'Ask for goodness in this life and the next. Your prayer can hold both present responsibilities and a horizon beyond them.', 'Duan bu dünyadaki iyiliği de ahiretteki iyiliği de kuşatsın. Bugünün sorumluluğunu üstlenirken daha geniş bir ufku hatırında tut.', ['prayer']),
  q('3:92', 'Âl-i İmrân', 'Sharing reaches deeper when you give from what you love. Notice what you hold most tightly, and make generosity a sincere choice.', 'Paylaşmak, sevdiğin şeyden verdiğinde derinleşir. Elinde en sıkı tuttuğun nimeti düşün; cömertliğin yalnızca artanlardan ibaret kalmasın.', ['generosity']),
  q('4:36', 'Nisâ', 'Look beyond your closest circle. The distant neighbour and the traveller also belong within the reach of your kindness.', 'İyiliğinin çevresini genişlet. Yakınların kadar uzak komşunun ve yolda kalanın da hâlini gözet; merhametin tanıdık yüzlerde son bulmasın.', ['community']),
  q('4:58', 'Nisâ', 'Return what has been entrusted to you to its rightful owner. Reliability gives everyday faith a shape others can depend on.', 'Sana emanet edileni sahibine hakkıyla teslim et. Güvenilirliğin, başkasının sana gönül rahatlığıyla dayanabilmesini sağlayan günlük bir sorumluluktur.', ['integrity']),
  q('4:86', 'Nisâ', 'When someone greets you, answer with equal warmth or more. A small welcome is an opportunity to strengthen human connection.', 'Sana verilen selâmı aynı güzellikle, mümkünse daha güzeliyle karşıla. Küçük bir karşılaşmayı, aranızdaki bağı güçlendirecek sıcaklığa dönüştür.', ['connection']),
  q('4:135', 'Nisâ', 'Tell the truth even when it challenges your own advantage. Justice asks you to see beyond wealth, family loyalty, and personal preference.', 'Doğruyu söylemek kendi çıkarına dokunsa da adaleti gözet. Yakınlık, zenginlik veya yoksulluk; bir insanın hakkını görmene perde olmasın.', ['courage', 'justice']),
  q('4:29', 'Nisâ', 'Let your dealings rest on genuine consent. Earning well includes respecting the rights and willingness of the other person.', 'Kazancında karşılıklı rızayı ve hakkaniyeti gözet. Bir alışverişin sana yarar sağlaması, karşındaki insanın hakkını önemsiz kılmaz.', ['integrity']),
  q('4:32', 'Nisâ', 'Do not turn another person’s gifts into resentment. Recognize your own effort and ask God for bounty without envying their share.', 'Başkasına verilen nimeti kıskançlığa dönüştürme. Kendi emeğinin hakkını gözet; Allah’ın lütfunu isterken başkasının nasibine darılma.', ['gratitude']),
  q('5:2', 'Mâide', 'Choose your companions in action by what you are building together. Help one another toward goodness, never toward harm or hostility.', 'Birlikte neye hizmet ettiğinize bak. İyilikte ve sorumlulukta birbirinize destek olun; dayanışmanız başkasına zarar vermenin aracına dönüşmesin.', ['community', 'action']),
  q('5:32', 'Mâide', 'Remember the immense worth of a single human life. An act that protects one person deserves your attention and effort.', 'Bir insanın hayatını korumanın ne büyük bir değer taşıdığını hatırla. Tek bir kişiye uzanan yardımını, yalnız bir kişi diye küçümseme.', ['compassion']),
  q('6:141', 'En‘âm', 'At harvest time, remember the share that should reach others. Let the moment you receive also become a moment of responsibility.', 'Emeğinin meyvesini toplarken başkasına ulaşması gereken payı unutma. Elinin dolduğu gün, paylaşma sorumluluğunun da hatırlandığı bir gün olsun.', ['gratitude', 'generosity']),
  q('6:152', 'En‘âm', 'Give full measure and speak fairly even about someone close to you. Care for another person’s rights in the smallest details.', 'Ölçüyü eksiltme; söz söylerken yakınını da adaletle değerlendir. Başkasının hakkına gösterdiğin özen, küçük ayrıntılarda da belli olsun.', ['justice']),
  q('7:31', 'A‘râf', 'Enjoy what nourishes you without waste. Receiving a blessing with care includes knowing when enough has been served.', 'Seni besleyen nimetlerden yararlan; israf etme. Sofradaki şükrün, yeterli olanı fark etmende ve artanı ziyan etmemende de görünsün.', ['gratitude']),
  q('7:56', 'A‘râf', 'Do not undo the good order around you. Turn to God with humility and hope, and be among those who care for what is entrusted to them.', 'Düzelmiş olanı bozma. Rabbine saygı ve ümitle yönelirken çevrendeki iyiliği korumaya da niyet et; elin onarmaya alışsın.', ['hope', 'care']),
  q('7:199', 'A‘râf', 'Choose a generous manner and avoid being pulled into ignorant quarrels. You can encourage what is right without answering every provocation.', 'Hoşgörülü davran, iyiyi hatırlat; cahilce bir çekişmenin içine sürüklenme. Her kışkırtmaya cevap vermeden de doğruya sahip çıkabilirsin.', ['calm']),
  q('7:204', 'A‘râf', 'When the Quran is recited, offer it your listening. Let a moment of quiet attention become part of how you receive its message.', 'Kur’an okunurken dinlemeye yer aç. Bir an durup dikkatini toplaman, duyduğun mesajı anlamaya yönelişinin ve ona gösterdiğin saygının parçası olsun.', ['faith', 'attention']),
  q('10:101', 'Yûnus', 'Look carefully at the heavens and the earth. Let wonder lead you beyond a passing glance into attentive observation.', 'Göklere ve yeryüzüne dikkatle bak. Merakın, şöyle bir göz gezdirmekle kalmasın; gördüğün şey üzerinde dur, anlamaya açık ol.', ['curiosity']),
  q('11:114', 'Hûd', 'A mistake need not become your only story. Return to prayer and good action; give the next moment a different direction.', 'Bir hatanın ardından yalnızca pişmanlığın içinde kalma. Namaza ve iyi davranışa dön; önündeki ana farklı bir yön vermeyi seç.', ['hope', 'renewal']),
  q('12:86', 'Yûsuf', 'Jacob brought his grief to God. You can name your sorrow in prayer without pretending your heart is unhurt.', 'Yakup, kederini Allah’a açtı. Sen de duanda hüznünü dile getirebilirsin; Rabbine yönelmek için incinmemiş gibi görünmen gerekmez.', ['hope', 'prayer']),
  q('12:92', 'Yûsuf', 'Joseph met his brothers with a path beyond reproach. Where reconciliation is possible, leave room for mercy instead of endlessly replaying blame.', 'Yusuf’un kardeşlerine açtığı merhamet kapısını düşün. Barışmanın mümkün olduğu yerde, aynı suçlamayı yeniden söylemek yerine affa alan aç.', ['mercy']),
  q('14:24-25', 'İbrâhîm', 'A wholesome word is pictured as a rooted tree bearing fruit. Choose words with depth, so their benefit can outlast the moment.', 'Güzel söz, kökü sağlam ve meyve veren bir ağaca benzetilir. Sözünü özenle seç; faydası, söylendiği anın ötesine uzanabilsin.', ['wisdom']),
  q('16:125', 'Nahl', 'Invite with wisdom and considerate counsel. In disagreement, seek the best manner of conversation rather than the sharpest way to win.', 'Hikmetle ve güzel öğütle davet et. Bir anlaşmazlıkta yalnızca üstün gelmeyi düşünme; konuşmanın en incelikli ve yapıcı yolunu ara.', ['communication']),
  q('16:43', 'Nahl', 'When you do not know, ask those who know the subject. A sincere question opens a door that pretending to know keeps closed.', 'Bilmediğinde, konuyu bilenlere sor. Bilir gibi görünme kaygısını bırak; samimi bir soru, öğrenmek için açtığın bir kapı olabilir.', ['courage', 'learning']),
  q('17:23-24', 'İsrâ', 'Meet your parents’ old age with a gentle voice. Remember the care that raised you, and make space for tenderness in return.', 'Anne babanın yaşlılığını yumuşak bir sesle karşıla. Seni büyüten emeği hatırla; cevabında, davranışında ve duanda şefkate yer ver.', ['compassion']),
  q('17:28', 'İsrâ', 'When you cannot offer material help, offer a considerate answer. Limited means do not require a cold heart or a harsh refusal.', 'Yardım edecek imkânın olmadığında bile gönül alıcı bir cevap verebilirsin. Elinin darlığı, sözünün sert olmasını gerektirmez.', ['kindness']),
  q('17:29', 'İsrâ', 'Let generosity stay in balance. Neither close your hand completely nor empty it so recklessly that you neglect your responsibilities.', 'Cömertliğinde dengeyi koru. Elini bütünüyle kapatma; fakat sorumluluklarını yerine getiremeyecek kadar ölçüsüzce dağıtmayı da iyilik sanma.', ['balance']),
  q('17:34', 'İsrâ', 'Treat a promise as something you will answer for. Before giving your word, consider whether you can carry its responsibility.', 'Verdiğin sözün sorumluluğunu hatırla. Birine umut vermeden önce, o sözü yerine getirmek için gerçekten ne üstleneceğini düşün.', ['integrity']),
  q('17:36', 'İsrâ', 'Do not follow a claim without knowledge. Your hearing, sight, and judgment deserve more care than a hurried assumption.', 'Bilgin olmayan bir iddianın peşine hemen düşme. Duyduğunu, gördüğünü ve vardığın hükmü dikkatle değerlendir; acele bir varsayımı gerçek yerine koyma.', ['discernment']),
  q('18:23-24', 'Kehf', 'Plan tomorrow with humility before God. Intention can be clear while the future remains beyond your complete command.', 'Yarın için niyetini belirlerken Allah’ın dilemesini hatırla. Planın açık olabilir; geleceğin bütünüyle elinde olmadığını kabul etmek de tevekkülün bir parçasıdır.', ['uncertainty', 'faith']),
  q('18:28', 'Kehf', 'Stay close to people whose devotion is sincere. Do not let the shine of status make you overlook a faithful heart.', 'Samimiyetle Rabbine yönelen insanlarla bağını koru. Gösterişin ve mevkinin parıltısı, içten bir kalbin değerini gözünden kaçırmasın.', ['connection']),
  q('18:46', 'Kehf', 'Possessions and family adorn this life, but lasting goodness offers a deeper hope. Give some attention to what your actions leave behind.', 'Mal ve evlat dünya hayatının süsüdür; kalıcı iyi işler ise daha derin bir umut taşır. Bugün ardından nasıl bir iyilik bırakabileceğini düşün.', ['hope', 'purpose']),
  q('18:66', 'Kehf', 'Moses asked permission to follow and learn. A willing learner can approach another person with curiosity, respect, and no need to appear complete.', 'Musa, öğrenmek için yol arkadaşlığı istedi. Sen de her şeyi biliyor görünmek zorunda değilsin; merakla, saygıyla ve öğrenmeye gönüllü bir kalple yaklaş.', ['courage', 'learning']),
  q('19:25', 'Meryem', 'Mary was asked to shake the palm tree. In a difficult hour, remember that receiving help and making an effort can stand together.', 'Meryem’e hurma ağacını silkelemesi söylendi. Zor bir anda, yardım beklemekle elinden gelen gayreti göstermek aynı kalpte bir arada bulunabilir.', ['courage', 'action']),
  q('20:25-28', 'Tâhâ', 'Before a difficult conversation, remember Moses’ prayer for an open heart and clear speech. Ask for ease in the task and understanding between people.', 'Zor bir konuşmadan önce Musa’nın duasını hatırla: gönül genişliği, işte kolaylık ve anlaşılır bir dil. Sözünün karşıya ulaşmasına niyet et.', ['fear', 'prayer']),
  q('21:83', 'Enbiyâ', 'Job named his suffering while remembering God’s mercy. Pain can be spoken honestly; it need not erase the language of trust.', 'Eyyub, derdini dile getirirken Rabbini merhametiyle andı. Acını dürüstçe söyle; zorlanıyor olman, güvenle dua etmene engel değildir.', ['hope', 'faith']),
  q('21:107', 'Enbiyâ', 'Remember the Prophet’s mission as mercy to the worlds. Let the faith you carry make your presence gentler for other living beings.', 'Peygamberin âlemlere rahmet oluşunu hatırla. Taşıdığın inanç, yanında bulunan canlıların daha çok şefkat ve merhamet görmesine vesile olsun.', ['mercy']),
  q('22:46', 'Hac', 'Travel with a heart willing to understand. Seeing places matters more when you also listen and learn from what happened there.', 'Yeryüzünde gezerken yalnız manzaraya bakma. Yaşananları dinleyen ve ibret almaya açık bir kalple yürü; gördüklerin anlayışını da genişletsin.', ['reflection']),
  q('23:1-3', 'Mü’minûn', 'Give prayer a collected heart, and step away from empty talk. Some space in your day is better filled with presence than noise.', 'Namazına gönül huzuruyla yönelmeye çalış; boş sözden uzaklaş. Gününün bazı aralıklarını gürültüyle doldurmak yerine dikkatini ve kalbini toplamak için ayır.', ['attention', 'faith']),
  q('24:27', 'Nûr', 'Ask permission before entering another person’s space. A respectful greeting begins with recognizing that welcome cannot be assumed.', 'Başkasının alanına girerken izin iste ve selâm ver. Yakınlık, sınırları yok saymak değildir; saygın, karşı tarafın rahatlığını gözetmekle başlar.', ['respect']),
  q('25:72', 'Furkân', 'Do not lend your presence to false witness. When empty hostility surrounds you, keep your dignity as you pass beyond it.', 'Yalancı tanıklığa ortak olma. Boş ve incitici bir ortamdan geçerken vakarını koru; oradaki her söze katılmak zorunda değilsin.', ['courage', 'integrity']),
  q('25:74', 'Furkân', 'Pray for the people closest to you to be a source of joy. Aspire to offer an example of goodness they can trust.', 'Sevdiklerinin göz aydınlığın olması için dua et. Aynı zamanda sen de güven veren bir iyilik örneği olmaya niyet et.', ['prayer', 'connection']),
  q('26:80', 'Şuarâ', 'Abraham remembered God as the giver of healing. In illness, a prayer for recovery can hold your vulnerability and your hope together.', 'İbrahim, hastalandığında şifayı Rabbinden bildi. Hastalık anında şifa için dua etmek, kırılganlığını ve umudunu aynı anda dile getirmene imkân verir.', ['hope', 'prayer']),
  q('27:19', 'Neml', 'Ask for the ability to recognize blessings and use them well. Gratitude reaches from what you received to the good you choose to do.', 'Nimeti fark etmeyi ve onunla hayırlı işler yapmayı dile. Şükrün, yalnız aldıklarını anmakta kalmasın; seçtiğin davranışlarda da karşılık bulsun.', ['gratitude', 'action']),
  q('28:24', 'Kasas', 'Moses helped, then rested in the shade and acknowledged his need before God. Service, rest, and a humble prayer can belong to the same day.', 'Musa yardım etti, sonra gölgeye çekilip Rabbine muhtaçlığını açtı. Senin gününde de iyilik, dinlenme ve içten bir dua yan yana bulunabilir.', ['hope', 'prayer']),
  q('29:20', 'Ankebût', 'Go out and consider how creation began. Let movement through the world become an invitation to investigate, not merely to pass by.', 'Yeryüzünde dolaş ve yaratılışın başlangıcı üzerine düşün. Yolculuğun yalnız yer değiştirmek olmasın; gözlem yapmaya ve araştırmaya da kapı açsın.', ['curiosity', 'action']),
  q('30:21', 'Rûm', 'A close bond can hold affection, mercy, and rest. Bring these qualities into the relationship you hope will give you peace.', 'Yakın bir bağda sevgi, merhamet ve huzur bir arada büyüyebilir. Huzur beklediğin ilişkiye, sen de şefkatle ve anlayışla katkıda bulun.', ['connection']),
  q('30:22', 'Rûm', 'Different languages and colours are signs worth contemplating. Meet human variety with curiosity and respect rather than a demand for sameness.', 'Dillerin ve renklerin farklılığını bir ayet olarak düşün. İnsanların çeşitliliğine saygı ve merakla yaklaş; herkesin sana benzemesini bekleme.', ['community']),
  q('30:50', 'Rûm', 'Notice the earth becoming alive after its barrenness. Let this sign of mercy make room in your reflection for renewal.', 'Kurumuş toprağın yeniden canlanışına dikkat et. Rahmetin bu eserini düşünürken, zihninde yalnız tükenişe değil yenilenmeye de yer aç.', ['hope', 'renewal']),
  q('31:19', 'Lokmân', 'Keep your pace measured and your voice gentle. You do not need to fill a space with noise to stand in it with purpose.', 'Yürüyüşünde ölçüyü, sesinde yumuşaklığı koru. Bir yerde kararlı biçimde bulunmak için o yeri gürültünle doldurman gerekmez.', ['calm']),
  q('49:11', 'Hucurât', 'Do not make someone the target of ridicule or a hurtful name. Their worth may be greater than the judgment you formed too quickly.', 'Bir insanı alayının veya kırıcı bir lakabın hedefi yapma. Onun değerini, aceleyle verdiğin hükümden daha büyük görmeye açık ol.', ['respect']),
  q('49:12', 'Hucurât', 'Protect another person’s privacy, including when they are absent. Refuse suspicion, prying, and gossip a place in the conversation you shape.', 'İnsanların mahremiyetini, yanlarında olmadıkları zaman da koru. Konuşmana yön verirken kötü zanna, gizli araştırmaya ve gıybete kapı açma.', ['integrity']),

  // 25 hadith passages, with exact collection references.
  h('Nawawi 40', 'Nevevî Kırk Hadis', '11', 'When an ethical choice leaves you doubtful, prefer the course whose rightness is clear. A clean decision is worth more than a convenient excuse.', 'Ahlaki bir seçim içine kuşku düşürdüğünde, doğruluğundan emin olduğun yola yönel. İçini rahatlatan dürüst bir tercih, kullanışlı bir bahaneden değerlidir.', ['discernment']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '12', 'Leave aside what needlessly draws you into other people’s affairs. Care for the responsibilities that genuinely belong to you.', 'Seni gereksiz yere başkalarının işine sürükleyen uğraşları bırak. Sana gerçekten düşen sorumluluklara özen göster; ilgini faydalı olabileceğin yere taşı.', ['attention']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '13', 'Wish another person the good you wish yourself. Let their opportunity become something you welcome, not something you must diminish.', 'Kendin için arzu ettiğin iyiliği kardeşin için de iste. Ona açılan bir imkânı küçültmek yerine gönülden karşılamaya çalış.', ['generosity']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '15', 'Make your guest feel honoured and your neighbour respected. Faith has an everyday expression in how safely people can be near you.', 'Misafirine ikram et, komşunun hakkını gözet. İnancının gündelik hayattaki karşılığı, insanların yanında gördüğü saygıda ve özeninde de belirginleşsin.', ['hospitality']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '21', 'Let your declaration of belief be followed by an upright course. When your direction becomes blurred, return to the honesty you chose.', 'İnandığını söyleyişinin ardından dosdoğru bir yol tut. Yönün bulanıklaştığında, benimsediğin dürüstlüğe yeniden dön ve davranışlarını onunla hizala.', ['faith', 'courage']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '23', 'Purification belongs to faith, and patience offers illumination. Give care to both your outer cleanliness and the way you carry difficulty.', 'Temizliği iman hayatının bir parçası olarak gözet; sabrı aydınlatıcı bir güç olarak hatırla. Dışına gösterdiğin özen, zorluğu taşıyışına da ulaşsın.', ['faith']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '24', 'Do not oppress one another. When you have power in a situation, remember that the other person’s vulnerability increases your responsibility.', 'Birbirinize zulmetmeyin. Bir durumda gücü elinde tuttuğunda, karşındaki kişinin kırılganlığının senin sorumluluğunu artırdığını hatırla.', ['justice']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '25', 'A lack of wealth does not close every door of giving. Remembrance, encouraging good, and resisting harm also belong to a generous life.', 'Maddi imkânın azlığı bütün hayır kapılarını kapatmaz. Zikir, iyiliği teşvik etmek ve kötülükten sakındırmak da paylaşabildiğin değerler arasındadır.', ['hope', 'generosity']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '26', 'Help reconcile two people, carry a burden, or remove an obstacle from the road. Ordinary movements can become acts of charity.', 'İki kişinin arasını bul, bir yükü taşımaya yardım et veya yoldaki engeli kaldır. Gündelik hareketlerin de sadakaya dönüşebileceğini hatırla.', ['action']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '27', 'Goodness includes the character you bring to a situation. Notice the conduct you would feel uneasy about exposing to others.', 'İyilik, bir duruma taşıdığın güzel ahlakla da ilgilidir. İnsanların görmesini istemeyeceğin bir davranışın içine düşerken durup kendini yokla.', ['conscience']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '32', 'Do not answer injury by creating another injury. Seek a remedy that protects rights without continuing the chain of harm.', 'Bir zarara karşılık verirken yeni bir zarar üretme. Hakkını koruyan, fakat incinmeyi başkasına taşımayan bir çözüm yolu ara.', ['restraint']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '34', 'Do not become indifferent to wrongdoing. According to your ability, work against it, speak truthfully, or at least refuse to approve it inwardly.', 'Yanlışa karşı duyarsızlaşma. Gücün ölçüsünde onu düzeltmeye çalış, doğruyu dile getir; buna imkân bulamadığında bile kalben onaylama.', ['courage', 'action']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '35', 'Do not build your relationships on envy, contempt, or turning away. Treat a fellow person’s dignity as something to guard.', 'İlişkilerini kıskançlık, küçümseme ve yüz çevirme üzerine kurma. Bir insanın onurunu, incitebileceğin bir yer değil koruyacağın bir değer olarak gör.', ['community']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '36', 'Ease one burden for someone in distress. Being there for another person is itself a way of seeking God’s help.', 'Sıkıntıda olan birinin yükünü hafiflet. Allah’ın yardımını ararken, sen de bir insana destek olabileceğin imkânı dikkatle gözet.', ['hope', 'service']),
  h('Nawawi 40', 'Nevevî Kırk Hadis', '39', 'Mistakes, forgetfulness, and coercion are not the same as deliberate wrongdoing. Let that distinction temper the harshness of your self-judgment.', 'Hata, unutma ve zorlanma; bile isteye yapılan kötülükle aynı değildir. Kendini değerlendirirken bu ayrımı hatırla, hükmünde merhamete de yer ver.', ['hope', 'self-compassion']),
  h('Bukhari', 'Buhârî', '5027', 'Give time to learning the Quran and helping someone else learn it. Understanding can become a shared act of service.', 'Kur’an’ı öğrenmeye ve bir başkasının öğrenmesine destek olmaya vakit ayır. Öğrencilikle öğretme gayreti, aynı hayır yolunda buluşabilir.', ['learning']),
  h('Bukhari', 'Buhârî', '6011', 'A caring community resembles one body: another person’s pain is not irrelevant to the rest. Let compassion interrupt your indifference.', 'Merhametli bir topluluğu tek bir beden gibi düşün: birinin acısı diğerlerinden kopuk değildir. Şefkatin, alışılmış kayıtsızlığını kesintiye uğratsın.', ['community']),
  h('Bukhari', 'Buhârî', '5353', 'Sustaining a widow or someone in poverty is deeply valued work. Quiet, practical care can carry the weight of great devotion.', 'Yoksulun ve dul kalmış kişinin geçimine destek olmak çok kıymetli bir emektir. Sessizce üstlendiğin somut bakımın değerini küçümseme.', ['service']),
  h('Bukhari', 'Buhârî', '2363', 'A thirsty animal is worthy of your compassion. Remember the person who drew water for a dog, and notice the need within reach.', 'Susamış bir hayvan da merhametine layıktır. Köpeğe su veren kişinin anlatısını hatırla; hemen yakınındaki bir canlının ihtiyacını fark et.', ['compassion', 'action']),
  h('Bukhari', 'Buhârî', '1975', 'Your body, eyes, and family have rights over you. Devotion should not make you forget sleep, rest, and those who share your life.', 'Bedeninin, gözlerinin ve ailenin üzerinde hakkı var. Gayretin; uykuyu, dinlenmeyi ve hayatını paylaştığın insanları bütünüyle unutturmasın.', ['balance']),
  h('Bukhari', 'Buhârî', '2444', 'Helping someone who is doing wrong can mean stopping their wrongdoing. Loyalty need not become permission for injustice.', 'Yanlış yapan birine yardımın, onu zulmünden alıkoymak olabilir. Bağlılığını her davranışı onaylamak sanma; gerektiğinde iyilik için sınır koy.', ['courage', 'justice']),
  h('Muslim', 'Müslim', '2593', 'Gentleness has a worth that harshness cannot provide. Try a considerate approach before assuming pressure is the only way forward.', 'Yumuşaklığın, sertliğin sağlayamayacağı bir değeri vardır. İlerlemenin tek yolunu baskı sanmadan önce, incelikli bir yaklaşımı dene.', ['kindness']),
  h('Muslim', 'Müslim', '2564c', 'Your appearance and possessions are not the measure of your standing before God. Attend to the heart and actions beneath what others see.', 'Allah katındaki değerini yalnız görünüşünle ve malınla ölçme. İnsanların gördüğü yüzün altında kalan kalbine ve yaptığın işlere özen göster.', ['self-worth']),
  h('Muslim', 'Müslim', '2664', 'Seek what benefits you and ask God for help. After an outcome, do not let endless if-only thoughts consume the strength needed for what comes next.', 'Sana faydalı olana gayret et ve Allah’tan yardım iste. Sonuçtan sonra bitmeyen keşkelerin, bundan sonrası için gereken gücünü tüketmesine izin verme.', ['courage', 'uncertainty']),
  h('Muslim', 'Müslim', '2588', 'Do not mistake forgiveness for humiliation or humility for worthlessness. A generous character has a dignity that display cannot supply.', 'Affetmeyi aşağılanmak, tevazuyu değersizleşmek sanma. Bağışlayıcı ve alçak gönüllü bir duruşun, gösterişle elde edilmeyen bir izzeti vardır.', ['courage', 'self-worth']),

  // 20 distinct reflections from Marcus Aurelius.
  marcus('4.3', '4.four', 'You can take a short retreat within your own reflection. Return to a few steady principles, then meet the world again with a clearer mind.', 'Kısa bir süre kendi içine çekil. Dayandığın birkaç sağlam ilkeyi hatırla; ardından dünyaya daha toplu bir zihinle yeniden dön.', ['fear', 'calm']),
  marcus('4.12', '4.four', 'Stay willing to revise a judgment when a better reason appears. A change made for truth is a form of steadiness, not a loss of direction.', 'Daha iyi bir gerekçe gördüğünde hükmünü yenilemeye açık ol. Doğru için fikir değiştirmek, yönünü kaybettiğin anlamına gelmez.', ['courage', 'learning']),
  marcus('4.20', '4.four', 'An emerald does not become less beautiful when nobody praises it. Let your work have a value that applause does not have to create.', 'Bir zümrüt, kimse övmediğinde güzelliğini kaybetmez. Emeğinin değerini yalnız alkışla ölçme; yaptığın işin kendi niteliğine de güven.', ['fear', 'self-worth']),
  marcus('4.24', '4.four', 'Ask whether each demand is truly necessary. Fewer needless actions and thoughts can leave more room for the work that actually matters.', 'Önündeki her talebin gerçekten gerekli olup olmadığını düşün. Gereksiz uğraşlar azaldığında, önemli olana daha sakin ve özenli yaklaşabilirsin.', ['fear', 'calm']),
  marcus('4.31', '4.four', 'Respect the craft you have learned, however modest it appears. Give it your care without turning yourself into anyone’s master or servant.', 'Öğrendiğin beceri sana mütevazı görünse de ona sahip çık. İşine özen gösterirken kimseye hükmetmeye veya kendini ezdirmeye ihtiyaç duyma.', ['courage', 'self-worth']),
  marcus('4.49', '4.four', 'Picture a headland holding steady as waves arrive. A difficult event can meet a response that preserves your fairness and composure.', 'Dalgalarla karşılaşan sağlam bir kıyıyı düşün. Zor bir olayın içinde, adaletini ve sükûnetini koruyacak bir duruş arayabilirsin.', ['fear', 'courage']),
  marcus('6.6', '6.six', 'Do not let a wrongdoer teach you how to become like them. Keep the character you want, even while responding to what happened.', 'Sana yanlış yapan kişinin davranışı, senin karakterinin öğretmeni olmasın. Olanlara karşılık verirken nasıl biri kalmak istediğini hatırla.', ['courage', 'integrity']),
  marcus('6.11', '6.six', 'Losing your balance for a moment does not require remaining unsettled. Return to yourself; the practice of returning strengthens your steadiness.', 'Bir an sarsılman, bütün gün dağınık kalmanı gerektirmez. Kendine yeniden dön; toparlanmayı tekrarladıkça dengenle kurduğun ilişki güçlenir.', ['fear', 'renewal']),
  marcus('6.19', '6.six', 'Do not declare something impossible simply because it is difficult for you now. Examine what human ability and practice can actually reach.', 'Şu anda sana zor gelen bir şeyi hemen imkânsız ilan etme. İnsan becerisinin ve çalışmanın gerçekte nereye ulaşabildiğine bak.', ['courage', 'hope']),
  marcus('6.20', '6.six', 'After an injury in training, caution need not become hatred. Protect yourself where necessary without letting every encounter become a battle.', 'Bir antrenmanda incindiğinde tedbir alırsın; mutlaka düşman edinmen gerekmez. Kendini korurken her karşılaşmayı bir savaşa dönüştürmemeye çalış.', ['fear', 'boundaries']),
  marcus('6.26', '6.six', 'Even your name is written one letter at a time. Approach a difficult duty through its actual parts, without adopting the surrounding agitation.', 'Adın bile harf harf yazılır. Zor bir işi oluşturan gerçek parçalara bak; çevrendeki telaşı üstlenmeden sırayla ilerlemeye çalış.', ['fear', 'action']),
  marcus('6.30', '6.six', 'Do not let a position of power dye your character. Keep your manner simple, just, and kind as your responsibilities grow.', 'Bir mevkinin karakterini boyamasına izin verme. Sorumluluğun büyürken de sadeliğini, adalet duygunu ve insanlara gösterdiğin inceliği koru.', ['integrity']),
  marcus('6.48', '6.six', 'Recall a friend’s courage, another’s generosity, another’s modesty. Real examples of goodness can renew your willingness to practise it.', 'Bir dostunun cesaretini, bir başkasının cömertliğini, diğerinin tevazuunu hatırla. Gördüğün somut iyilik örnekleri, senin de gayretini tazeleyebilir.', ['hope', 'connection']),
  marcus('6.53', '6.six', 'Listen closely enough to enter the speaker’s meaning. Understanding another person calls for a little less preparation of your own reply.', 'Konuşanın ne demek istediğini anlayacak kadar dikkatle dinle. Kendi cevabını hazırlamaya biraz ara vermek, başka bir zihne yaklaşmanı sağlar.', ['listening']),
  marcus('8.1', '8.eight', 'You cannot rewrite how your earlier life appeared. You can still choose the character of the life that remains, without waiting for a perfect reputation.', 'Geçmiş hayatının başkalarına nasıl göründüğünü yeniden yazamazsın. Kusursuz bir itibar beklemeden, bundan sonrasını nasıl yaşayacağına özen gösterebilirsin.', ['fear', 'renewal']),
  marcus('8.11', '8.eight', 'When something intimidates you, examine what it actually consists of, what causes it, and how long it lasts. Precision can loosen its vague authority.', 'Bir şey gözünü korkuttuğunda, onun neyden oluştuğuna, nedenlerine ve süresine bak. Belirsiz bir büyüklük yerine somut ayrıntılar görmeye çalış.', ['fear', 'discernment']),
  marcus('8.36', '8.eight', 'Do not gather every possible hardship of a lifetime into this moment. Look at the difficulty actually present and respond to that.', 'Bir ömrün bütün muhtemel sıkıntılarını şu ana yığma. Önünde gerçekten bulunan güçlüğe bak; karşılığını önce ona vermeye çalış.', ['fear', 'uncertainty']),
  marcus('8.50', '8.eight', 'If the cucumber is bitter, put it aside; if the path has thorns, step around them. A practical response need not await an explanation of everything.', 'Salatalık acıysa bırak, yolda diken varsa çevresinden geç. Uygulanabilir bir çözüm için her şeyin nedenini bütünüyle açıklaman gerekmeyebilir.', ['fear', 'action']),
  marcus('8.51', '8.eight', 'Keep actions purposeful and speech clear. A crowded inner life need not pull you into hurried movements in every direction.', 'Yaptıklarında amaç, söylediklerinde açıklık ara. İçinin kalabalık oluşu seni her yöne savuran acele hareketlere dönüşmek zorunda değil.', ['fear', 'calm']),
  marcus('8.59', '8.eight', 'People exist in relation to one another. When someone falls short, consider whether patient teaching or patient understanding is possible.', 'İnsanlar birbirleriyle ilişki içinde yaşar. Birinin eksiğiyle karşılaştığında, sabırla anlatmanın veya anlayış göstermenin mümkün olup olmadığını düşün.', ['community']),

  // 15 different sections of Epictetus, with practical rather than punitive wording.
  epictetus('4', 'Before entering a busy place, expect ordinary interruptions. Prepare both to do your task and to preserve the manner you want to bring to it.', 'Kalabalık bir işe girmeden önce olağan aksilikleri hesaba kat. Hem işini yapmaya hem de orada korumak istediğin tavra hazırlan.', ['fear', 'preparation']),
  epictetus('6', 'A fine possession is not your own achievement of character. Take satisfaction in the judgment and conduct that are truly yours to practise.', 'Güzel bir eşyaya sahip olmak, tek başına karakter başarın değildir. Kendi payın olan muhakemeye ve davranışa gösterdiğin özenle de memnuniyet duy.', ['self-worth']),
  epictetus('10', 'Meet each challenge by asking which capacity it calls for: endurance, restraint, or patience. Name the strength you can bring before deciding you have none.', 'Bir güçlükle karşılaşınca hangi yeteneğine ihtiyaç olduğunu sor: dayanıklılık mı, ölçü mü, sabır mı? Gücün yok demeden önce kullanabileceğin gücü tanı.', ['fear', 'courage']),
  epictetus('12', 'When a little oil spills, notice the price of making it a great disturbance. Practise accepting small losses without surrendering all your peace.', 'Biraz yağ döküldüğünde, bunu büyük bir huzursuzluğa çevirmenin bedelini fark et. Küçük kayıplarda bütün sükûnetinden vazgeçmemeyi dene.', ['fear', 'calm']),
  epictetus('13', 'Learning may make you look inexperienced. Allow that stage; protecting the appearance of knowing can prevent the work of becoming capable.', 'Öğrenirken acemi görünebilirsin. O evreye izin ver; her şeyi biliyor görünmeye çalışmak, gerçekten beceri kazanmanın önünü kapatabilir.', ['courage', 'learning']),
  epictetus('15', 'At a banquet, receive what reaches you without grabbing what has not. Practise a patient, measured relationship with opportunities and possessions.', 'Bir sofrada sana uzananı ölçüyle al, henüz gelene uzanıp çekiştirme. İmkânlarla ilişkinin acele ve kapma duygusuyla yönetilmesine izin verme.', ['patience']),
  epictetus('17', 'An actor may not choose the length of the role. Give care to how you perform the part now entrusted to you.', 'Oyuncu rolünün uzunluğunu her zaman seçemez. Sen de önüne gelen payın büyüklüğüne takılıp kalmadan, onu nasıl üstlendiğine özen göster.', ['uncertainty', 'courage']),
  epictetus('20', 'Between an insult and your reply, allow a little time. That pause can help you choose a response instead of merely continuing the provocation.', 'Bir hakaretle cevabın arasına biraz zaman koy. O kısa ara, kışkırtmayı sürdürmek yerine nasıl karşılık vereceğini seçmene yardım edebilir.', ['fear', 'calm']),
  epictetus('24', 'You need not purchase influence at the cost of integrity. Being a trustworthy friend and citizen is already a meaningful contribution.', 'Nüfuz kazanmak için dürüstlüğünü bedel olarak vermen gerekmez. Güvenilir bir dost ve sorumluluk sahibi bir insan olmak da değerli bir katkıdır.', ['courage', 'self-worth']),
  epictetus('25', 'An invitation may have a price in flattery or time. When you decline that price, remember what you kept as well as what you missed.', 'Bir davetin bedeli bazen dalkavukluk veya sürekli ilgi olabilir. O bedeli ödemediğinde, kaçırdığın kadar koruduğun şeyi de hatırla.', ['fear', 'boundaries']),
  epictetus('28', 'Do not give every passing insult unlimited access to your attention. Guard your judgment as deliberately as you would guard your physical space.', 'Her gelip geçen hakarete dikkatinin tamamını teslim etme. Fiziksel alanını gözettiğin gibi, zihnine hangi sözü taşıdığına da özen göster.', ['fear', 'boundaries']),
  epictetus('29', 'Before choosing the contest, understand its training and costs. Let informed commitment support the enthusiasm that first drew you toward the goal.', 'Bir yarışa girmeden önce gerektirdiği hazırlığı ve bedelleri öğren. Hedefe duyduğun ilk hevesi, ne üstlendiğini bilen bir kararlılıkla destekle.', ['courage', 'preparation']),
  epictetus('35', 'If careful judgment shows an action is right, do not abandon it merely because others may misunderstand. Examine the act, then face mistaken criticism.', 'Dikkatli değerlendirmen bir davranışın doğru olduğunu gösteriyorsa, yalnız yanlış anlaşılmaktan korktuğun için vazgeçme. Önce davranışı incele, sonra eleştiriyi karşıla.', ['fear', 'courage']),
  epictetus('43', 'A relationship may offer more than one handle: the injury, or the bond you share. Consider which way of holding it allows a wiser response.', 'Bir ilişkiyi yalnız incindiğin yerden tutmak zorunda değilsin. Aranızdaki bağı da düşün; hangi bakışın daha bilgece bir karşılığa imkân verdiğini ara.', ['perspective']),
  epictetus('45', 'Describe what you observed before adding a judgment of character. Knowing the action is not the same as knowing the reason behind it.', 'Birinin karakteri hakkında hüküm vermeden önce, gerçekten ne gördüğünü tarif et. Davranışı görmekle, arkasındaki nedeni bilmek aynı şey değildir.', ['discernment']),

  // 10 distinct arguments from Aristotle.
  aristotle('3.2', '3.iii', 'A wish alone is not a choice. A considered choice concerns an action you can take, so bring your desire into a decision you can carry out.', 'Dilemek tek başına seçim yapmak değildir. Düşünülmüş bir seçim, yapabileceğin bir eylemle ilgilidir; isteğini üstlenebileceğin bir karara yaklaştır.', ['action']),
  aristotle('3.3', '3.iii', 'For a difficult decision, consult others and trace the available means. Begin with the step that your reasoning has brought within reach.', 'Zor bir kararda başkalarının görüşüne başvur ve mümkün yolları incele. Düşünmenin sonunda erişilebilir hâle gelen ilk işle başlamayı dene.', ['uncertainty', 'action']),
  aristotle('3.4', '3.iii', 'What looks pleasant is not always what serves you well. Examine the apparent good before allowing it to decide your direction.', 'Hoş görünen her şey sana gerçekten iyi gelmeyebilir. Yönünü belirlemesine izin vermeden önce, çekici bulduğun şeyin değerini sorgula.', ['discernment']),
  aristotle('3.6', '3.iii', 'Fear is not automatically a defect. Some fears protect what deserves care; examine what you fear before judging yourself for feeling it.', 'Korku duyman kendiliğinden bir kusur değildir. Bazı korkular özen göstermeye değer olanı korur; kendini yargılamadan önce neyden korktuğuna bak.', ['fear', 'self-compassion']),
  aristotle('3.7', '3.iii', 'Courage considers the real danger, the right time, and a worthy purpose. It asks for proportionate action, not a performance of fearlessness.', 'Cesaret; gerçek tehlikeyi, doğru zamanı ve değerli bir amacı birlikte gözetir. Korkusuz görünmeye çalışmaktan önce, duruma uygun davranmayı ara.', ['fear', 'courage']),
  aristotle('3.8', '3.iii', 'Experience can make a danger less confusing, while anger can imitate courage. Build informed confidence without letting excitement make the decision for you.', 'Deneyim, tehlikeyi daha anlaşılır kılabilir; öfke ise cesarete benzeyebilir. Kararını heyecana bırakmadan, bilgiyle desteklenen bir güven geliştir.', ['fear', 'courage']),
  aristotle('3.9', '3.iii', 'A courageous act may still be painful. Its worth can lie in the good it protects, even when the experience itself is not pleasant.', 'Cesur bir davranış yine de zor ve acı verici olabilir. Yaşadığın an hoş olmasa bile, koruduğun değer o davranışı anlamlı kılabilir.', ['fear', 'courage']),
  aristotle('6.5', '6.vi', 'Practical wisdom asks what serves a good life as a whole. Do not let cleverness about one advantage replace care for the wider picture.', 'Pratik bilgelik, hayatın bütününe neyin iyi geleceğini sorar. Tek bir avantajı elde etme becerin, daha geniş resmi gözetmenin yerini almasın.', ['wisdom']),
  aristotle('6.7', '6.vi', 'General knowledge needs attention to the particular situation. Before applying a rule, look closely at the person and circumstances before you.', 'Genel bilgi, somut duruma dikkatle yaklaşmaya ihtiyaç duyar. Bir kuralı uygulamadan önce, önündeki insanı ve koşulları yakından anlamaya çalış.', ['discernment']),
  aristotle('8.3', '8.viii', 'A lasting friendship wishes the other person well for their own sake. Give the bond more care than the usefulness you receive from it.', 'Kalıcı dostluk, ötekinin iyiliğini onun kendisi için ister. Aranızdaki bağı, yalnızca ondan aldığın faydayla ölçmeden beslemeye çalış.', ['friendship']),

  // 15 passages from the Analects; chapter 1.4 is explicitly attributed to Zengzi.
  confucius('1.1', 'There is a quiet pleasure in learning and returning to what you learned. Let practice be an experience you can enjoy, not merely an exam to pass.', 'Öğrenmenin ve öğrendiğine yeniden dönmenin sakin bir sevinci vardır. Çalışmanı yalnız geçilecek bir sınav olarak değil, tadına varılacak bir uğraş olarak da gör.', ['learning']),
  p('Zengzi', 'Zengzi', 'Analects', 'Konuşmalar', '1.4', 'https://www.gutenberg.org/cache/epub/3330/pg3330-images.html', 'At day’s end, examine your reliability to others, sincerity with friends, and practice of what you learned. Reflection becomes useful when it asks something specific.', 'Gün biterken başkalarına karşı güvenilirliğini, dostlarına samimiyetini ve öğrendiklerini uygulayışını düşün. Kendine belirli sorular sormak, muhasebeni daha anlamlı kılar.', ['reflection']),
  confucius('7.10', 'Choose companions who prepare carefully before acting. Recklessness is not the same as courage; resolve can include respect for the danger.', 'Harekete geçmeden önce dikkatle hazırlanan insanlarla yol al. Pervasızlığı cesaret sanma; kararlı bir duruş, tehlikeyi ciddiye almayı da içerebilir.', ['fear', 'courage']),
  confucius('1.16', 'When recognition feels scarce, turn some attention toward understanding others. Being known is not the only meaningful direction for your curiosity.', 'Yeterince tanınmadığını hissettiğinde, insanları tanımaya da dikkat ayır. Merakının tek yönü başkalarının seni nasıl gördüğü olmasın.', ['fear', 'connection']),
  confucius('2.11', 'Return to earlier knowledge with fresh questions. Reviewing what you already know can open the way to an understanding you did not have before.', 'Eski bilgine yeni sorularla dön. Bildiğini gözden geçirmek, yalnız tekrar değildir; daha önce göremediğin bir anlayışın kapısını açabilir.', ['learning']),
  confucius('2.15', 'Let study and reflection correct one another. Reading without thought leaves understanding thin; thinking without learning can lose its bearings.', 'Öğrenmeyle düşünmenin birbirini beslemesine izin ver. Üzerinde durmadığın bilgi yüzeyde kalabilir; öğrenmeyle sınamadığın düşünce ise yönünü şaşırabilir.', ['learning']),
  confucius('2.17', 'Knowing includes being honest about what you do not know. Say so plainly; uncertainty acknowledged is a sounder beginning than confidence performed.', 'Bilmek, bilmediğini dürüstçe kabul etmeyi de içerir. Açıkça söyle; kabul edilmiş bir belirsizlik, sergilenen yapay bir güvenden daha sağlam bir başlangıçtır.', ['uncertainty', 'courage']),
  confucius('4.17', 'When you see admirable conduct, consider learning from it. When you see a fault, also ask whether a trace of it needs attention in yourself.', 'Güzel bir davranış gördüğünde ondan öğrenmeyi düşün. Bir kusur gördüğünde ise kendinde benzer bir izin olup olmadığını da yokla.', ['reflection']),
  confucius('6.18', 'Knowing a subject is one stage; loving it and finding joy in it deepen the relationship. Make room for what draws your curiosity back.', 'Bir konuyu bilmek bir aşamadır; onu sevmek ve ondan sevinç duymak bağı derinleştirir. Merakını yeniden çağıran tarafına da zaman ayır.', ['curiosity']),
  confucius('7.21', 'Among the people walking beside you, there is something to learn. Choose a good quality to practise and a poor example to avoid.', 'Yanında yürüyen insanlarda öğrenebileceğin bir şey vardır. Birinin iyi yönünü örnek al; yanlış bulduğun davranıştan da kendine bir ders çıkar.', ['learning', 'community']),
  confucius('9.27', 'Winter reveals the lasting green of pine and cypress. A difficult season can make steadfast qualities visible that easy weather left unnoticed.', 'Kış geldiğinde çamın ve servinin yeşili daha belirginleşir. Zor bir dönem, rahat günlerde fark edilmeyen sağlam niteliklerini görünür kılabilir.', ['hope', 'courage']),
  confucius('12.4', 'When fear troubles you, examine whether your conduct gives your conscience reason for reproach. An honest inner review can support a steadier stance.', 'Korku seni sıkıştırdığında, davranışlarında vicdanını rahatsız eden bir şey olup olmadığını düşün. Dürüst bir iç değerlendirme, daha sağlam durmana yardımcı olabilir.', ['fear', 'conscience']),
  confucius('13.23', 'Harmony does not require everyone to be identical. You can remain in respectful relationship while keeping an honest difference of view.', 'Uyum, herkesin aynı düşünmesini gerektirmez. Görüş ayrılığını dürüstçe korurken saygılı bir ilişki içinde kalmayı da öğrenebilirsin.', ['courage', 'community']),
  confucius('15.20', 'Bring your standard of conduct back to what you ask of yourself. Responsibility becomes clearer when it is not always directed at someone else.', 'Davranış ölçünü, kendinden ne beklediğine de çevir. Sorumluluğu sürekli başkasına yöneltmediğinde, sana düşen pay daha açık görünür.', ['responsibility']),
  confucius('15.29', 'The deeper mistake is to leave a recognized mistake uncorrected. Once you can see it, give yourself permission to repair it.', 'Asıl büyüyen yanlış, fark ettiğin hatayı düzeltmeden bırakmandır. Görebildiğin anda onarmaya yönel; değişmek için kendine izin ver.', ['courage', 'renewal']),

  // Five different images from Laozi; none repeats the existing thousand-mile line.
  lao('8', 'Water benefits what surrounds it without demanding the highest place. Seek a useful contribution without needing every room to recognise your rank.', 'Su, en yüksek yeri istemeden çevresindekileri besler. Her ortamda mevkinin tanınmasına ihtiyaç duymadan, faydalı bir katkı sunmanın yolunu ara.', ['humility']),
  lao('11', 'A vessel is useful because it has room inside. Leave some unfilled space in your day; capacity also depends on what you do not crowd in.', 'Bir kap, içindeki boşluk sayesinde kullanılabilir. Gününde doldurmadığın bir alan bırak; taşıma kapasiten, her aralığı doldurmamana da bağlıdır.', ['calm']),
  lao('15', 'Muddy water clears when it is allowed to settle. When your thinking is stirred up, pause before forcing a conclusion.', 'Bulanık su, durulmasına izin verildiğinde berraklaşır. Zihnin karıştığında hemen bir sonuç çıkarmaya zorlama; düşüncelerinin yatışmasına biraz zaman tanı.', ['fear', 'calm']),
  lao('23', 'A fierce wind does not last all morning, nor a sudden rain all day. Do not take the intensity of a moment as its permanence.', 'Şiddetli rüzgâr bütün sabah, ani yağmur bütün gün sürmez. İçinden geçtiğin bir anın yoğunluğunu, onun sonsuza kadar süreceği sanısıyla karıştırma.', ['fear', 'hope']),
  lao('24', 'Standing on tiptoe does not make a stable stance. Let your effort find a sustainable posture instead of straining to appear taller.', 'Parmak ucunda durmak sağlam bir duruş sağlamaz. Daha büyük görünmek için sürekli gerilmek yerine, gayretini taşıyabileceğin bir denge bul.', ['fear', 'balance']),
];

export const FAITH_QUOTES: SourcedQuote[] = drafts.map((quote, index) => ({
  id: `faith-${String(index + 1).padStart(3, '0')}`,
  ...quote,
}));
